:root {
/* Scaling and Density Control Tokens */
  --mw-density-factor: 1;
  --mw-scaling-factor: 1;
/* Spacing Tokens */
  --mw-spacing-xs: calc(2px * var(--mw-scaling-factor) * var(--mw-density-factor));
  --mw-spacing-sm: calc(4px * var(--mw-scaling-factor) * var(--mw-density-factor));
  --mw-spacing-md: calc(8px * var(--mw-scaling-factor) * var(--mw-density-factor));
  --mw-spacing-lg: calc(12px * var(--mw-scaling-factor) * var(--mw-density-factor));
  --mw-spacing-xl: calc(16px * var(--mw-scaling-factor) * var(--mw-density-factor));
  --mw-spacing-2xl: calc(24px * var(--mw-scaling-factor) * var(--mw-density-factor));
  --mw-spacing-3xl: calc(32px * var(--mw-scaling-factor) * var(--mw-density-factor));
/* Font Size Tokens */
  --mw-fontSize-xs: calc(10px * var(--mw-scaling-factor));
  --mw-fontSize-sm: calc(11px * var(--mw-scaling-factor));
  --mw-fontSize-md: calc(12px * var(--mw-scaling-factor));
  --mw-fontSize-lg: calc(14px * var(--mw-scaling-factor));
  --mw-fontSize-xl: calc(16px * var(--mw-scaling-factor));
  --mw-fontSize-2xl: calc(18px * var(--mw-scaling-factor));
  --mw-fontSize-3xl: calc(20px * var(--mw-scaling-factor));
/* Icon Size Tokens */
  --mw-iconSize-sm: calc(12px * var(--mw-scaling-factor));
  --mw-iconSize-md: calc(16px * var(--mw-scaling-factor));
  --mw-iconSize-lg: calc(24px * var(--mw-scaling-factor));
}
