    font-size: 16px;
    cursor: pointer;
    padding: 3px 10px;
    margin-right: -3.5px;
}

mw-mos-home-recent-artifacts .artifacts-toggle.true-toggle {
    border-bottom: 3px solid var(--mw-color-hyperlink);
    color: var(--mw-color-hyperlink);
    cursor: default;
    font-weight: bold;
}

mw-mos-home-recent-artifacts .artifacts-toggle:not(.true-toggle):hover {
    background: var(--mw-backgroundColor-primary);
