    color: var(--mw-color-hyperlink);
    text-decoration: none;
    font-size: 16px;
    cursor: pointer;
    margin: 10px 0;
    outline-offset: 3px;
    grid-area: left;
}

mw-mos-home-recent-artifacts .show-more::after {
    content: url(home/0.55.0/images/arrow-down-link.35775.da2d.svg);
