mw-mos-home-recent-artifacts .resource-name{
    display: flex;
    flex-direction: column;
    color: var(--mw-color-primary);
    font-size: 14px;
    font-weight: 500;
    padding: 5px;
}

mw-mos-home-recent-artifacts .double-chevron {
    background: url(home/0.55.0/images/chevron-right.1942.1b54.svg) 0/12px 12px no-repeat;
