mw-mos-home-chat-eval-capture .ec-section {
    border-bottom: 1px solid var(--mw-borderColor-secondary);
}

mw-mos-home-chat-eval-capture .ec-section:last-child {
    border-bottom: none;
}

mw-mos-home-chat-eval-capture .ec-section-header {
    padding: 6px 12px;
    background: #fcfcfc;
    font-size: 11px;
    font-weight: 600;
    color: var(--mw-color-secondary);
    text-transform: uppercase;
    letter-spacing: 0.5px;
    cursor: pointer;
    user-select: none;
}

mw-mos-home-chat-eval-capture .ec-section-header:hover {
    background: #f5f5f5;
}

mw-mos-home-chat-eval-capture .ec-section-header::before {
    content: '▸ ';
}

mw-mos-home-chat-eval-capture .ec-section-header.open::before {
    content: '▾ ';
}

mw-mos-home-chat-eval-capture .ec-section-header:focus-visible {
    outline: 2px solid var(--mw-borderColor-focus);
    outline-offset: -2px;
}

mw-mos-home-chat-eval-capture .ec-code {
    padding: 8px 12px;
    background: #f8f8f8;
    color: var(--mw-color-primary);
    font-family: 'SF Mono', 'Fira Code', monospace;
    font-size: 12px;
    line-height: 1.5;
    white-space: pre-wrap;
    overflow-x: auto;
    max-height: 200px;
    overflow-y: auto;
}

mw-mos-home-chat-eval-capture .ec-output {
    padding: 8px 12px;
    background: #fafafa;
    font-family: 'SF Mono', monospace;
    font-size: 12px;
    line-height: 1.4;
    white-space: pre-wrap;
    color: var(--mw-color-primary);
    max-height: 200px;
    overflow-y: auto;
}

mw-mos-home-chat-eval-capture .ec-figures {
    padding: 8px;
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 8px;
}

mw-mos-home-chat-eval-capture .ec-figures img {
    width: 100%;
    border-radius: 4px;
    border: 1px solid var(--mw-borderColor-secondary);
    cursor: pointer;
}

mw-mos-home-chat-eval-capture .ec-figures.single-fig {
    grid-template-columns: 1fr;
}

mw-mos-home-chat-eval-capture .ec-figures.single-fig img {
    max-height: 400px;
    object-fit: contain;
}

mw-mos-home-chat-eval-capture .ec-actions {
    display: flex;
    gap: 8px;
    padding: 8px 12px;
    background: #fcfcfc;
    border-top: 1px solid var(--mw-borderColor-secondary);
}

mw-mos-home-chat-eval-capture .ec-action {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 4px 12px;
    border: 1px solid var(--mw-borderColor-info);
    border-radius: 6px;
    background: var(--mw-color-white);
    color: var(--mw-borderColor-info);
    font-size: 12px;
    font-family: 'Roboto', sans-serif;
    cursor: pointer;
    transition: background-color 0.15s ease, color 0.15s ease;
}

mw-mos-home-chat-eval-capture .ec-action:hover {
    background: var(--mw-borderColor-info);
    color: var(--mw-color-white);
}

mw-mos-home-chat-eval-capture .ec-action:focus-visible {
    outline: 2px solid var(--mw-borderColor-focus);
    outline-offset: 2px;
}

mw-mos-home-chat-eval-capture .ec-action.ec-action-primary {
    margin-left: auto;
    background: var(--mw-borderColor-info);
    color: var(--mw-color-white);
}

mw-mos-home-chat-eval-capture .ec-action.ec-action-primary:hover {
    background: var(--mw-color-white);
    color: var(--mw-borderColor-info);
}

mw-mos-home-chat-eval-capture [hidden] {
    display: none;
}

/*# sourceMappingURL=data:application/json;base64, */</style><style>mw-mos-home-chat-window {
    width: 100%;
    display: block;
}

mw-mos-home-chat-window .chat-window {
    box-sizing: border-box;
    padding: 12px 25px;
    border: 1px solid var(--mw-borderColor-secondary);
    border-radius: 12px;
    background-image: linear-gradient(
        135deg,
        var(--mw-color-blue100) 0%,
        #f4f0fb 100%
    );
}

mw-mos-home-chat-window .chat-window-extras {
    margin-bottom: 12px;
    padding: 12px;
    background-color: var(--mw-color-white);
    border: 1px solid var(--mw-borderColor-secondary);
    border-radius: 8px;
    max-height: 275px;
    overflow-y: auto;
}

mw-mos-home-chat-window .chat-window-extras mw-mos-home-chat-message {
    display: block;
    margin-bottom: 8px;
}

mw-mos-home-chat-window .chat-window-pending {
    font-size: 14px;
    font-style: italic;
    color: var(--mw-color-secondary);
    margin: 4px 0;
}

mw-mos-home-chat-window .chat-window-error {
    font-size: 14px;
    color: var(--mw-color-error);
    margin: 4px 0;
}

mw-mos-home-chat-window .chat-window-chips {
    display: flex;
    flex-wrap: wrap;
    gap: 10px;
}

mw-mos-home-chat-window .chat-window-chip {
    display: inline-flex;
    align-items: center;
    padding: 8px 16px;
    border: 1px solid var(--mw-borderColor-info);
    border-radius: 20px;
    background-color: var(--mw-color-blue100);
    color: var(--mw-borderColor-info);
    font-size: 14px;
    font-family: 'Roboto', sans-serif;
    white-space: nowrap;
    cursor: pointer;
    transition: border-color 0.15s ease, background-color 0.15s ease, color 0.15s ease;
}

mw-mos-home-chat-window .chat-window-chip:hover {
    border-color: var(--mw-borderColor-info);
    background-color: var(--mw-borderColor-info);
    color: var(--mw-color-white);
}

mw-mos-home-chat-window .chat-window-chip:focus-visible {
    outline: 2px solid var(--mw-borderColor-focus);
    outline-offset: 2px;
}

mw-mos-home-chat-window .chat-window-header {
    display: flex;
    align-items: center;
    gap: 12px;
    margin: 0 0 16px 0;
}

mw-mos-home-chat-window .chat-window-enlarge {
    flex-shrink: 0;
    margin-left: auto;
    align-self: flex-start;
    width: 32px;
    height: 32px;
    padding: 0;
    border: none;
    border-radius: 6px;
    background: url(home/0.55.0/images/enlarge.20936.6107.svg) no-repeat center center;
    background-size: 18px 18px;
    cursor: pointer;
    transition: background-color 0.15s ease, opacity 0.15s ease;
}

mw-mos-home-chat-window .chat-window--enlarged .chat-window-enlarge {
    background-image: url(home/0.55.0/images/shrink.22969.faaf.svg);
}

mw-mos-home-chat-window .chat-window-enlarge:hover {
    background-color: rgba(6, 123, 194, 0.12);
}

mw-mos-home-chat-window .chat-window-enlarge:focus-visible {
    outline: 2px solid var(--mw-borderColor-focus);
    outline-offset: 2px;
}

mw-mos-home-chat-window .chat-window-backdrop {
    position: fixed;
    inset: 0;
    background: var(--mw-backgroundColor-overlay);
    opacity: 50%;
    z-index: 1000;
}

mw-mos-home-chat-window .chat-window--enlarged {
    position: fixed;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    width: min(860px, 92vw);
    max-height: 88vh;
    overflow-y: auto;
    z-index: 1001;
    box-shadow: 0 8px 32px var(--mw-boxShadowColor);
    padding-bottom: 20px;
}

mw-mos-home-chat-window .chat-window--enlarged .chat-window-extras {
    max-height: 60vh;
}

body.mw-chat-window-enlarged-open {
    overflow: hidden;
}

mw-mos-home-chat-window .chat-window-header::before {
    content: '';
    flex-shrink: 0;
    width: 40px;
    height: 40px;
    background-image: url(home/0.55.0/images/ai-stars.30432.fc5e.svg);
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
}

mw-mos-home-chat-window .chat-window-heading {
    display: flex;
    flex-direction: column;
    justify-content: center;
}

mw-mos-home-chat-window .chat-window-subtitle {
    margin: 0;
    font-size: 16px;
    color: var(--mw-color-primary);
    text-align: left;
}

mw-mos-home-chat-window .chat-window-prompt {
    display: flex;
    align-items: center;
    gap: 16px;
}

mw-mos-home-chat-window .chat-window-input {
    position: relative;
    flex: 1 1 auto;
}

mw-mos-home-chat-window .chat-window-textbox {
    box-sizing: border-box;
    width: 100%;
    padding: 8px 48px 8px 20px;
    border: 1px solid var(--mw-borderColor-info);
    border-radius: 10px;
    background-color: var(--mw-color-white);
    color: var(--mw-color-primary);
    font-size: 14px;
    font-family: 'Roboto', sans-serif;
    outline: none;
}

mw-mos-home-chat-window .chat-window-textbox::placeholder {
    color: var(--mw-color-secondary);
}

mw-mos-home-chat-window .chat-window-textbox:focus {
    border-color: var(--mw-borderColor-focus);
    box-shadow: 0 0 0 1px var(--mw-borderColor-focus);
}

mw-mos-home-chat-window .chat-window-send {
    position: absolute;
    top: 50%;
    right: 12px;
    transform: translateY(-50%);
    width: 20px;
    height: 16px;
    padding: 0;
    border: none;
    border-radius: 4px;
    background: url(home/0.55.0/images/send.31192.7b63.svg) no-repeat center center;
    background-size: contain;
    cursor: pointer;
    transition: opacity 0.15s ease;
}

mw-mos-home-chat-window .chat-window-send:hover:not(:disabled) {
    opacity: 0.7;
}

mw-mos-home-chat-window .chat-window-send:disabled {
    cursor: default;
    opacity: 0.4;
}

mw-mos-home-chat-window .chat-window-send:focus-visible {
    outline: 2px solid var(--mw-borderColor-focus);
    outline-offset: 2px;
}

mw-mos-home-chat-window .chat-window-toggle-row {
    display: flex;
    justify-content: flex-end;
}

mw-mos-home-chat-window .chat-window-toggle {
    display: inline-flex;
    align-items: center;
    background-color: transparent;
    border: none;
    padding: 0px;
    color: var(--mw-color-hyperlink);
    text-decoration: none;
    font-size: 16px;
    cursor: pointer;
    margin: 10px 0;
    outline-offset: 3px;
}

mw-mos-home-chat-window .chat-window-toggle::after {
    content: url(home/0.55.0/images/arrow-down-link.35775.da2d.svg);
    margin-left: 10px;
    width: 16px;
    height: 16px;
    flex-shrink: 0;
    transition: transform 0.15s ease;
}

mw-mos-home-chat-window .chat-window-toggle[aria-expanded="true"]::after {
    transform: rotate(180deg);
}

mw-mos-home-chat-window .chat-window-title {
    margin: 0 0 4px 0;
    font-size: 16px;
    font-weight: 700;
    color: var(--mw-color-primary);
    text-align: left;
}

