/*# sourceMappingURL=data:application/json;base64, */</style><style>mw-mos-home-loading-screen {
    display: none;
}

mw-mos-home-loading-screen.shown {
    display: block;
}

.loading-screen-overlay {
    --ls-logo-width: 133px;
    --ls-logo-height: 115px;

    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    z-index: 99;
    background-color: var(--mw-backgroundColor-primary);
}

.loading-screen-overlay::before {
    content: '';
    position: absolute;
    top: 0;
    right: 0;
    width: 100%;
    height: 100%;
    background: url(home/0.55.0/images/membrane_mesh.7556.c5fe.png) center / cover no-repeat;
    pointer-events: none;
}

.loading-screen-content {
    position: relative;
    width: 100%;
    height: 100%;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
}

.loading-screen-matlab-logo {
    width: var(--ls-logo-width);
    height: var(--ls-logo-height);
    background-image: url(home/0.55.0/images/l-membrane-rgb.48237.cf89.png);
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
}

.loading-screen-loading-text {
    margin-top: 50px;
    font-family: Roboto, sans-serif;
    font-size: 20px;
    font-weight: 400;
    font-style: normal;
    line-height: normal;
    letter-spacing: 2px;
    color: var(--mw-color-secondary);
}

.loading-screen-loading-text::before {
    content: '...';
    visibility: hidden;
}

.loading-screen-loading-text::after {
    content: '';
    animation: loadingDots 2.5s step-end infinite;
}

@keyframes loadingDots {
    0% { content: ''; }
    20% { content: '.'; }
    40% { content: '..'; }
    60% { content: '...'; }
    100% { content: '...'; }
}

.loading-screen-card {
    margin-top: 50px;
}

/* Fade-out transition for dismissal */
mw-mos-home-loading-screen.fading-out {
    opacity: 0;
    transition: opacity 400ms ease-out;
}

/* Interrupted state: blur overlay, hide loading content */
mw-mos-home-loading-screen.interrupted .loading-screen-overlay {
    background-color: transparent;
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
}

mw-mos-home-loading-screen.interrupted .loading-screen-overlay::before {
    display: none;
}

mw-mos-home-loading-screen.interrupted .loading-screen-center {
    visibility: hidden;
}

