.has-session .home-nav mw-matrix button:hover>.icon-matrix {
  fill: var(--mw-color-primary)
}


.has-session .home-nav mw-matrix.matrix-desktop {
  padding-left: 8px;
  padding-top: 4px;
}

.has-session .home-nav mw-matrix.hide-matlab-drive ul[class*="matrix_links_"] > li:has(a[id="matrix_link_matlab_drive"]) {
  display: none;
}

.home-nav mw-matrix .icon-matrix {
  height: 24px; 
}

.home-nav mw-matrix span[class*="icon-"]:not(.glyphicon) {
  border: 0px;
}

mw-matrix button:focus-visible {
  outline-offset: 2px;
}

/* General mw-matrix theme overrides in support of dark mode - see g3390920 */

mw-matrix a:focus-visible {
  outline:3px solid var(--mw-borderColor-focus);
  outline-offset: 1px;
}

.home-nav mw-matrix .matrix_container, .matrix_container_mobile {
  background: var(--mw-backgroundColor-tertiary);
}

.home-nav mw-matrix .matrix_container ul[class*="matrix_links_"] > li > a {
  color: var(--mw-color-hyperlink) !important;
}

.home-nav mw-matrix .matrix_container ul[class*="matrix_links_"] > li > a:hover > img,
.home-nav mw-matrix .matrix_container ul[class*="matrix_links_"] > li.matrix_active > a > img {
  background: var(--mw-backgroundColor-tertiary);
}

/* End theme overrides in support of dark mode */
/*# sourceMappingURL=data:application/json;base64, */</style><style>
