    display: grid;
    grid-template-rows: 60px 1fr;
    height: 100%;
}

mw-mos-session-banner .underlay{
    background: var(--mw-backgroundColor-overlay);
    opacity: 0%;
    width: 100%;
    height: 100%;
    position: absolute;
    z-index:1;
    top: 60px;
}

mw-mos-session-banner .top-bar {
    border-bottom: 1px solid var(--mw-borderColor-info);
    background: var(--mw-backgroundColor-secondary-info);
    font-size: 14px;
    display: flex;
    align-items: center;
    padding: 11px 11px 15px 11px;

}

mw-mos-session-banner .icon {
    position: relative;
    float: left;
    flex: 0 0 30px;
    height: 30px;
    background-size: cover;
    margin-right: 10px;
    background-image: url(home/0.55.0/images/banner-info.67633.cb80.svg);
}

mw-mos-session-banner p {
    flex-grow: 1;
    font-weight: bold;   
}

@media (max-width: 550px) {
  mw-mos-session-banner p {
    max-width: 250px;
    min-width: 0; /* important for flex children to shrink properly */
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
  }
}

mw-mos-session-banner .button-area {
    display: flex;
    gap: 10px;
}

mw-mos-session-banner button {
    background-color: var(--mw-backgroundColor-tertiary);
    color: var(--mw-color-brand1);
    min-width: 75px;
    display: flex;
    height: 34px;
    padding: 10px 14px 9px 14px;
    justify-content: center;
    align-items: center;
    gap: 4px;
    cursor: pointer;
    border-radius: 4px;
    border: 1px solid var(--mw-color-brand1);
}

mw-mos-session-banner button:focus{
    outline-offset: 2px;
}

mw-mos-session-banner button:hover {
    background-color: #0076A8;
    color: #FFFFFF;
    border-color: #FFFFFF;
}

mw-mos-session-banner button.primary {
    white-space: nowrap;
    background-color: var(--mw-color-brand1);
    color: var(--mw-backgroundColor-tertiary);
    width: 196px;
}

mw-mos-session-banner button.primary:hover {
    background-color: #08609D;
}

mw-mos-session-banner button.primary::before {
    content: url(home/0.55.0/images/membrane_white.20811.947c.svg);
    margin-right: 4px;
    margin-top: 4px;
    width: 15px;
    height: 20px;
    flex-shrink: 0;
}

mw-mos-session-banner button.primary::after {
    content: url(home/0.55.0/images/arrow-open-down.43123.4f45.svg);
    margin-left: 4px;
    margin-top: 4px;
    flex-shrink: 0;
}


mw-mos-session-banner .dropdown-content {
    display: none;
    position: absolute;
    top: 45px;
    right: 10px;
    width: 200px;
    background-color: var(--mw-backgroundColor-tertiary);
    min-width: 160px;
    padding: 7px 0;
    z-index: 1;
    border: 1px solid var(--mw-borderColor-secondary);
    box-shadow: 0px 2px 4px var(--mw-boxShadowColor);
}

mw-mos-session-banner .dropdown-content.show {
    display: block;
}

mw-mos-session-banner  .dropdown-content .open-menu-item {
    width: 100%;
    justify-content: left;
    border: none;
    font: inherit;
    background-color: var(--mw-backgroundColor-tertiary);
    white-space: pre;
    cursor: pointer;
    color: var(--mw-backgroundColor-inputFill);
    margin: 0;
    padding: 2px 20px;
}
  
mw-mos-session-banner  .dropdown-content .open-menu-item:hover {
    background-color: var(--mw-backgroundColor-primary);
}

mw-mos-session-banner  .dropdown-content .open-menu-item:focus {
    outline: 2px solid var(--mw-borderColor-focus);
    outline-offset: -2px;
}

mw-mos-session-banner .main-content {
    background: var(--mw-backgroundColor-tertiary);
}
