    } catch (e) {
    }
  }

  function updatePlayhead(player) {
    if (!player._hbTracker || !player._hbSessionStarted) {
      return;
    }

    try {
      var currentTime = getCurrentPlayhead(player);
      var previousPlayhead = player._hbLastObservedPlayhead;

      if (previousPlayhead == null || Math.abs(currentTime - previousPlayhead) > PLAYHEAD_MOVEMENT_EPSILON) {
        player._hbLastPlayheadMovementAt = nowMs();
      }

      player._hbLastObservedPlayhead = currentTime;
      player._hbTracker.updatePlayhead(currentTime);
    } catch (e) {
    }
  }

  function hasSessionExpiredFromNoPlayheadMovement(player) {
    if (!player || !player._hbSessionStarted || !player._hbLastPlayheadMovementAt) {
      return false;
    }

    return nowMs() - player._hbLastPlayheadMovementAt >= SESSION_NO_PLAYHEAD_MOVEMENT_MS;
  }

  function startSessionWhenReady(player, Media) {
    if (!player || !player._hbTracker || player._hbSessionStarted) {
      return;
    }

    if (!player._hbPlayIntent) {
      return;
    }

    var meta = getVideoMetadata(player, Media);

    if (!meta.length || meta.length <= 0) {
      return;
    }

    var startingPlayhead = getCurrentPlayhead(player);

    var mediaObject = Media.createMediaObject(
      meta.name,
      meta.id,
      meta.length,
      getStreamTypeConstant(Media, meta.streamType),
      meta.mediaType
    );

    if (startingPlayhead >= 1) {
      try {
        mediaObject[Media.MediaObjectKey.MediaResumed] = true;
      } catch (e) {
      }
    }

    player._hbTracker.trackSessionStart(mediaObject, meta.contextData);

    player._hbSessionStarted = true;
    player._hbVideoStarted = true;
    player._hbLastObservedPlayhead = startingPlayhead;
    player._hbLastPlayheadMovementAt = nowMs();

    updatePlayhead(player);

    if (player._hbPendingPlay) {
      player._hbPendingPlay = false;
      trackPlay(player, Media);
    }
  }

  function trackPlay(player, Media) {
    if (!player._hbTracker) {
      return;
    }

    if (!player._hbSessionStarted) {
      player._hbPendingPlay = true;
      startSessionWhenReady(player, Media);
      return;
    }

    updatePlayhead(player);

    if (!player._hbFirstPlayHandled) {
      player._hbFirstPlayHandled = true;

      var satellite = getSatellite();

      if (satellite) {
        try {
          satellite.track('videoMeta');
        } catch (e) {
        }
      }

      player._hbTracker.trackPlay();
    } else if (player._hbVideoStarted) {
      player._hbTracker.trackPlay();
    }

    showVideoPlayerCaptions(player);
  }

  function trackPause(player, Media) {
    if (player._hbTracker && player._hbSessionStarted) {
      updatePlayhead(player);
      player._hbTracker.trackPause();
    }
  }

  function trackSeekStart(player, Media) {
    if (player._hbTracker && player._hbSessionStarted) {
      updatePlayhead(player);
      player._hbTracker.trackEvent(Media.Event.SeekStart);
    }
  }

  function trackSeekComplete(player, Media) {
    if (player._hbTracker && player._hbSessionStarted) {
      updatePlayhead(player);
      player._hbTracker.trackEvent(Media.Event.SeekComplete);
    }
  }

  function trackCompleteAndEnd(player, Media) {
    if (player._hbTracker && player._hbSessionStarted) {
      updatePlayhead(player);

      try {
        player._hbTracker.trackComplete();
        player._hbTracker.trackSessionEnd();
      } catch (e) {
      }
    }

    player._hbVideoStarted = false;
    player._hbSessionStarted = false;
    player._hbPendingPlay = false;
    player._hbPlayIntent = false;
    player._hbFirstPlayHandled = false;
    player._hbLastObservedPlayhead = null;
    player._hbLastPlayheadMovementAt = 0;
  }

  function endSessionOnUnload(player, Media) {
    if (!player || !player._hbTracker || !player._hbSessionStarted) {
      return;
    }

    updatePlayhead(player);

    try {
      player._hbTracker.trackSessionEnd();
    } catch (e) {
    }

    player._hbVideoStarted = false;
    player._hbSessionStarted = false;
    player._hbPendingPlay = false;
    player._hbPlayIntent = false;
    player._hbFirstPlayHandled = false;
    player._hbLastObservedPlayhead = null;
    player._hbLastPlayheadMovementAt = 0;
  }

  function attachUnloadListeners(player, Media) {
    if (player._hbUnloadListenersAttached) {
      return;
    }

    player._hbUnloadListenersAttached = true;

    function handlePageHide() {
      endSessionOnUnload(player, Media);
    }

    function handleBeforeUnload() {
      endSessionOnUnload(player, Media);
    }

    try {
      window.addEventListener('pagehide', handlePageHide, true);
      window.addEventListener('beforeunload', handleBeforeUnload, true);
    } catch (e) {
    }
  }

  function attachPlayerListeners(player, Media) {
    if (player._hbListenersAttached) {
      return;
    }

    player._hbListenersAttached = true;

    player.on('loadedmetadata', function () {
      updatePlayhead(player);

      if (player._hbPlayIntent) {
        startSessionWhenReady(player, Media);
      }
    });

    player.on('durationchange', function () {
      updatePlayhead(player);

      if (player._hbPlayIntent) {
        startSessionWhenReady(player, Media);
      }
    });

    player.on('canplay', function () {
      if (player._hbPlayIntent) {
        startSessionWhenReady(player, Media);
      }
    });

    player.on('play', function () {
      player._hbPlayIntent = true;

      if (hasSessionExpiredFromNoPlayheadMovement(player)) {
        try {
          player._hbTracker.trackSessionEnd();
        } catch (e) {
        }

        player._hbSessionStarted = false;
        player._hbVideoStarted = false;
        player._hbPendingPlay = true;
        player._hbFirstPlayHandled = false;
      }

      startSessionWhenReady(player, Media);
      trackPlay(player, Media);
    });

    player.on('timeupdate', function () {
      updatePlayhead(player);
    });

    player.on('pause', function () {
      trackPause(player, Media);
    });

    player.on('seeking', function () {
      trackSeekStart(player, Media);
    });

    player.on('seeked', function () {
      trackSeekComplete(player, Media);
    });

    player.on('ended', function () {
      trackCompleteAndEnd(player, Media);
    });

    attachUnloadListeners(player, Media);
  }
//ACS-starts tracker initialization.
  function initializeForPlayer(player, frameWindow) {
    if (!player) {
      return;
    }

    var MAApi = getMAApi();

    if (!MAApi) {
      return;
    }

    var Media = MAApi.Media;

    if (player._hbTrackerInitializing || player._hbTracker) {
      return;
    }

    player._hbTrackerInitializing = true;
    player._hbFrameWindow = frameWindow || window;

    player.ready(function () {
      var result = createHeartbeatInstance(Media);

      function onTrackerReady(tracker) {
        if (!tracker) {
          player._hbTrackerInitializing = false;
          return;
        }

        player._hbTracker = tracker;
        player._hbTrackerInitializing = false;
        player._hbSessionStarted = false;
        player._hbFirstPlayHandled = false;
        player._hbVideoStarted = false;
        player._hbPendingPlay = false;
        player._hbPlayIntent = false;
        player._hbLastObservedPlayhead = null;
        player._hbLastPlayheadMovementAt = 0;

        attachPlayerListeners(player, Media);

        try {
          if (typeof player.paused === 'function' && !player.paused()) {
            player._hbPlayIntent = true;
            player._hbPendingPlay = true;
            startSessionWhenReady(player, Media);
          }
        } catch (e) {
        }
      }

      if (result && typeof result.then === 'function') {
        result
          .then(onTrackerReady)
          .catch(function () {
            player._hbTrackerInitializing = false;
          });
      } else {
        onTrackerReady(result);
      }
    });
  }
//ACS-directly checks videojs.players for an obvious player
  function bootstrapKnownPlayer() {
    var api = getMAApi();
    var player = null;

    try {
      if (window.videojs && window.videojs.players) {
        var playerKeys = Object.keys(window.videojs.players);

        if (playerKeys.length === 1) {
          player = window.videojs.players[playerKeys[0]];
        } else if (window.videojs.players.videoPlayer) {
          player = window.videojs.players.videoPlayer;
        }
      }
    } catch (e) {
      player = null;
    }

    if (!api || !player) {
      return false;
    }

    if (!player._hbTracker && !player._hbTrackerInitializing) {
      initializeForPlayer(player, window);
      return true;
    }

    return false;
  }
//ACS - Polls and repeatedly looks for a usable Brightcove/Video.js player and starts initialization.
  function pollForPlayerAndInit() {
    if (!bootstrapKnownPlayer() && (!isPlayerLibraryReadyInAnyWindow() || !isPlayerReadyFlagSatisfied())) {
      state.pollCount++;

      if (state.pollCount < MAX_POLLS) {
        window.setTimeout(pollForPlayerAndInit, POLL_MS);
      }

      return;
    }

    var contexts = getPlayerContexts();

    for (var i = 0; i < contexts.length; i++) {
      var context = contexts[i];

      if (context && context.player && !context.player._hbTracker && !context.player._hbTrackerInitializing) {
        initializeForPlayer(context.player, context.frameWindow);
      }
    }

    state.pollCount++;

    if (state.pollCount < MAX_POLLS) {
      window.setTimeout(pollForPlayerAndInit, POLL_MS);
    }
  }

  pollForPlayerAndInit();
})();
});</script><script>
